class Counter(object):
    def __init__(self, start):
        self.value = start
        self.steps = 0

    def increment(self):
        self.value += 1
        self.steps += 1
        return self.value

    def reset(self):
        self.value = 0
        return self.value

    def __repr__(self):
        return 'Counter(%d)' % self.value
class Inbox:
    def __init__(self, owner):
        self.owner = owner
        self.messages = []

    def receive(self, message):
        self.messages.append(message)
        return len(self.messages)

    def unread(self):
        return [m for m in self.messages if not m.seen]

    def clear(self):
        self.messages = []
