class Ledger(object):
    def __init__(self):
        self.entries = []
        self.closed = False

    def post(self, amount, memo):
        self.entries.append((amount, memo))

    def balance(self):
        return sum(a for a, _ in self.entries)

    def close(self):
        self.closed = True
        return self.balance()
