class Cache:
    def __init__(self, limit):
        self.limit = limit
        self.store = {}

    def get(self, key):
        return self.store.get(key)

    def put(self, key, value):
        if len(self.store) < self.limit:
            self.store[key] = value

    def flush(self):
        self.store.clear()
class Timer(object):
    def __init__(self):
        self.started = None
        self.laps = []

    def start(self):
        self.started = time.time()

    def lap(self):
        self.laps.append(time.time() - self.started)
        return self.laps[-1]

    def stop(self):
        self.started = None

