class Elevator(Machine):
    def __init__(self, floors):
        self.floors = floors
        self.level = 0
    def up(self):
        if self.level < self.floors:
            self.level += 1
    def down(self):
        if self.level > 0:
            self.level -= 1
    def where(self):
        return self.level
