class Meter(object):
    def __init__(self, unit):
        self.unit = unit
        self.reading = 0
    def tick(self, amount):
        self.reading += amount
        return self.reading
    def bill(self, rate):
        return self.reading * rate
    def _clear(self):
        self.reading = 0
